-- PRESIDENTE 2026 no banco: cargo + 12 candidatos + votos por municipio
-- nos DOIS turnos + comparecimento do 2o turno. LULA REELEITO
-- 51,79% x 48,21% (PA: 55,02% x 44,98%). Fonte: totalizacao oficial TSE.
-- Idempotente.


UPDATE Candidato SET eleito = 1 WHERE id IN (SELECT ca.id FROM Candidato ca JOIN Cargo c ON ca.cargoId = c.id JOIN Eleicao e ON c.eleicaoId = e.id WHERE e.ano = 2026 AND c.nome = 'Presidente' AND ca.numero = 13);

DELETE FROM Resultado WHERE id LIKE 'r26p-%';
CREATE TEMP TABLE tmp_pres26 (turno INTEGER, numero INTEGER, cod TEXT, votos INTEGER);

SELECT 'r26p-' || t.turno || '-' || t.numero || '-' || t.cod,
  (SELECT ca.id FROM Candidato ca JOIN Cargo c ON ca.cargoId = c.id JOIN Eleicao e ON c.eleicaoId = e.id
   WHERE e.ano = 2026 AND c.nome = 'Presidente' AND ca.numero = t.numero),
  m.id, t.turno, t.votos, datetime('now')
FROM tmp_pres26 t JOIN Municipio m ON m.codigoTse = t.cod;
DROP TABLE tmp_pres26;

DELETE FROM Comparecimento WHERE ano = 2026 AND turno = 2;
CREATE TEMP TABLE tmp_c2 (cod TEXT, aptos INTEGER, comp INTEGER);

SELECT 'comp26t2-' || t.cod, m.id, 2026, 2, t.aptos, t.comp
FROM tmp_c2 t JOIN Municipio m ON m.codigoTse = t.cod;
DROP TABLE tmp_c2;